"""Low level interaction functions for the Single Sign-on (SSO)/ IAM Login UI. This is typically associated with the Monaco application,
and can be launched by either the Monaco.exe application or the AdaptivePlanningWorkflow.exe application."""
from .objects.sso_objects import SingleSignOnObjects
from . import common_monaco_ops as MonacoCommonOps
from interops.libraries.squish_actions import CommonActions
import interops.libraries.desktop.aut_manager as AutManager
from interops.libraries.squish_actions.constants import MONACO_APP_NAME
import os, sys, time


# Stores the AUT process name - this is set when the SingleSignOnLogin() page object class is instantiated.
# It Ensures the correct squish application context is set - either "Monaco" or "AdaptivePlanningWorkflow",
# depending on which process has been used to launch the SSO login window.
aut_ctx_registry =  {"sso_login_aut_ctx": MONACO_APP_NAME}

def __find_sso_login_window() -> bool:
    """Searches for the main SSO login window. Returns True if successfully located and in a ready state.

    -> Hidden function that should not be used outside the context of the sso_login.py file context!

    :return: True or False
    :rtype: bool
    """
    # Set the correct AUT context depending on which process that launched the SSO login window
    AutManager.set_app_context(autName=aut_ctx_registry["sso_login_aut_ctx"])
    return True if CommonActions.find_object(SingleSignOnObjects.main_Single_Sign_On_Window) is not None else False


def enter_username(username: str) -> None:
    """Locates the Username text box on SSO login window > types in the given Username string.

    :param str username: Username to be entered into the Username textbox
    """
    username_field_image_path = os.path.abspath(os.path.join(
        MonacoCommonOps.get_monaco_image_folder_path(), "sso_username_field_image.png"))
    username_field_image2_path = os.path.abspath(os.path.join(
        MonacoCommonOps.get_monaco_image_folder_path(), "sso_username_field_image2.png"))

    # Set the correct AUT context depending on which process that launched the SSO login window
    AutManager.set_app_context(autName=aut_ctx_registry["sso_login_aut_ctx"])
    if __find_sso_login_window():
        image_search_options = {"timeout": 5000, "threshold": 95.0}
        image_search_area = CommonActions.find_object(SingleSignOnObjects.main_Single_Sign_On_Window)
        try:
            username_field = CommonActions.wait_for_image_object(username_field_image_path, image_search_options, image_search_area)
        except Exception as e:
            # Try alternate username field image if the first fails
            username_field = CommonActions.wait_for_image_object(username_field_image2_path, image_search_options, image_search_area)

        if username_field is not None:
            CommonActions.left_click_object_no_move(username_field)
            CommonActions.native_text_type(username)
            time.sleep(1)


def enter_password(password: str) -> None:
    """Locates the Password text box on the SSO login window > types in the given Password string.

    :param str password: Password to be entered into the Password textbox
    """
    password_field_image_path = os.path.abspath(os.path.join(
        MonacoCommonOps.get_monaco_image_folder_path(), "sso_password_field_image.png"))
    password_field_image2_path = os.path.abspath(os.path.join(
        MonacoCommonOps.get_monaco_image_folder_path(), "sso_password_field_image2.png"))

    # Set the correct AUT context depending on which process that launched the SSO login window
    AutManager.set_app_context(autName=aut_ctx_registry["sso_login_aut_ctx"])
    if __find_sso_login_window():
        image_search_options = {"timeout": 5000, "threshold": 95.0}
        image_search_area = CommonActions.find_object(SingleSignOnObjects.main_Single_Sign_On_Window)
        try:
            password_field = CommonActions.wait_for_image_object(password_field_image_path, image_search_options, image_search_area)
        except Exception as e:
            password_field = CommonActions.wait_for_image_object(password_field_image2_path, image_search_options, image_search_area)

        if password_field is not None:
            CommonActions.left_click_object_no_move(password_field)
            CommonActions.native_text_type(password)
            time.sleep(1)


def click_sign_in_button() -> None:
    """Locates the Sign In Button on the SSO login > clicks located object using the primary mouse button.
    """
    signin_button_image_path = os.path.abspath(os.path.join(
        MonacoCommonOps.get_monaco_image_folder_path(), "sso_sign_in_button_image.png"))

    # Set the correct AUT context depending on which process that launched the SSO login window
    AutManager.set_app_context(autName=aut_ctx_registry["sso_login_aut_ctx"])
    if __find_sso_login_window():
        image_search_options = {"timeout": 5000, "threshold": 95.0}
        image_search_area = CommonActions.find_object(SingleSignOnObjects.main_Single_Sign_On_Window)
        sign_in_button = CommonActions.wait_for_image_object(signin_button_image_path, image_search_options, image_search_area)

        if sign_in_button is not None:
            CommonActions.left_click_object_no_move(sign_in_button)
            time.sleep(1)


def wait_for_sso_login_winfow_to_disappear(waitTimeout: int = 3) -> bool:
    """Wait for the SSO login window to disappear after a specified amount of time

    :param int waitTimeout: Time to wait for the SSO login window to disappear
    """
    # Set the correct AUT context depending on which process that launched the SSO login window
    AutManager.set_app_context(autName=aut_ctx_registry["sso_login_aut_ctx"])
    return CommonActions.wait_for_object_to_disappear(SingleSignOnObjects.main_Single_Sign_On_Window, waitTimeout)


def set_sso_aut_process(ssoAutProcess:str) -> None:
    """Set the AUT process used for attaching to the SSO login window. This is used to ensure the
    AUT context (either Monaco or AdaptivePlanningWorkflow) is correctly set for all SSO login interactions.

    :param str ssoAutProcess: "Monaco" or "AdaptivePlanningWorkflow" string
    """
    aut_ctx_registry["sso_login_aut_ctx"] = ssoAutProcess
